<?php $page_title='Find Food'; require_once 'includes/header.php';
$q=trim($_GET['q']??'');$category=trim($_GET['category']??'');$where="WHERE f.status='available' AND f.expiry_date>=CURDATE()";$params=[];if($q!==''){$where.=' AND (f.title LIKE ? OR f.description LIKE ? OR f.location LIKE ? OR f.category LIKE ?)';$like="%$q%";$params=[$like,$like,$like,$like];}if($category!==''){$where.=' AND f.category=?';$params[]=$category;}$stmt=$pdo->prepare("SELECT f.*,u.name donor_name FROM food_donations f JOIN users u ON u.id=f.donor_id $where ORDER BY f.created_at DESC");$stmt->execute($params);$items=$stmt->fetchAll();$categories=$pdo->query("SELECT DISTINCT category FROM food_donations WHERE status='available' ORDER BY category")->fetchAll(PDO::FETCH_COLUMN);
?>
<section class="page-hero"><span class="kicker">FOOD DIRECTORY</span><h1>Find food near you.</h1><p>Search active donations, use the nearby map for distance and request exactly what your community needs.</p><form class="searchbar"><input name="q" value="<?=e($q)?>" placeholder="Search meals, categories, locations..."><select name="category"><option value="">All categories</option><?php foreach($categories as $c):?><option value="<?=e($c)?>" <?=$category===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><button class="btn primary">Search</button></form></section>
<section class="section compact"><div class="section-heading"><div><span class="kicker">SMART DISCOVERY</span><h2><?=count($items)?> active listing<?=count($items)!==1?'s':''?></h2></div><a class="btn ghost" href="location.php">📍 Open nearby map</a></div><div class="food-grid"><?php foreach($items as $item):?><article class="food-card" data-lat="<?=e($item['latitude'])?>" data-lng="<?=e($item['longitude'])?>"><div class="food-image-wrap"><img class="food-image" src="<?=e(image_url($item['image']))?>" alt="<?=e($item['title'])?>"><span class="food-image-badge">FIBIN</span></div><div class="food-card-body"><div class="row"><span class="badge success">Available</span><span class="muted"><?=e($item['category'])?></span></div><h3><?=e($item['title'])?></h3><p><?=e($item['description']?:'Food donation available for community pickup.')?></p><div class="food-meta"><span>📦 <?=intval($item['quantity'])?> <?=e($item['unit'])?></span><span>📍 <?=e($item['location'])?></span></div><div class="food-meta"><span>👤 <?=e($item['donor_name'])?></span><span>⏳ <?=e(date('d M',strtotime($item['expiry_date'])))?></span></div><div class="food-meta"><span class="countdown" data-expiry="<?=e($item['expiry_date'])?>">Calculating...</span></div><a class="card-link" href="request.php?food_id=<?=intval($item['id'])?>">Request this food →</a></div></article><?php endforeach;if(!$items):?><div class="empty-state full"><h3>No matching food found</h3><p>Try another search or check the nearby map.</p></div><?php endif;?></div></section>
<?php require_once 'includes/footer.php'; ?>
